package com.gimtracker;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Small HTTP client for talking to the group's tracker server.
 * All calls are asynchronous and never block the client thread.
 */
@Slf4j
@Singleton
public class ApiClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	private final OkHttpClient http;
	private final Gson gson;
	private final GimTrackerConfig config;

	@Inject
	ApiClient(OkHttpClient http, Gson gson, GimTrackerConfig config)
	{
		this.http = http;
		this.gson = gson;
		this.config = config;
	}

	private HttpUrl baseUrl(String path)
	{
		HttpUrl base = HttpUrl.parse(config.serverUrl());
		if (base == null)
		{
			return null;
		}
		return base.newBuilder().addPathSegments(path).build();
	}

	private Request.Builder authed(HttpUrl url)
	{
		return new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + config.groupToken());
	}

	/** POST a state update (presence, events, bank snapshot) to the server. */
	public void postUpdate(Object payload)
	{
		post("api/update", payload, null);
	}

	/** Generic POST with optional success callback (called off the client thread). */
	public void post(String path, Object payload, Runnable onSuccess)
	{
		HttpUrl url = baseUrl(path);
		if (url == null || config.groupToken().isEmpty())
		{
			return;
		}

		Request request = authed(url)
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();

		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("GIM Tracker POST failed: {}", path, e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				boolean ok = response.isSuccessful();
				response.close();
				if (ok && onSuccess != null)
				{
					onSuccess.run();
				}
			}
		});
	}

	/** GET the current group state (members, activity, bank summary) for the side panel. */
	public void fetchGroup(Consumer<JsonObject> onSuccess)
	{
		getJson(baseUrl("api/group"), onSuccess);
	}

	/** Search the group bank by item name. */
	public void searchBank(String query, Consumer<JsonObject> onSuccess)
	{
		HttpUrl url = baseUrl("api/bank/search");
		if (url == null)
		{
			return;
		}
		url = url.newBuilder().addQueryParameter("q", query).build();
		getJson(url, onSuccess);
	}

	/** Poll for Discord chat messages newer than the given id. */
	public void fetchChat(long since, Consumer<JsonObject> onSuccess)
	{
		HttpUrl url = baseUrl("api/chat");
		if (url == null)
		{
			return;
		}
		url = url.newBuilder().addQueryParameter("since", Long.toString(since)).build();
		getJson(url, onSuccess);
	}

	private void getJson(HttpUrl url, Consumer<JsonObject> onSuccess)
	{
		if (url == null || config.groupToken().isEmpty())
		{
			return;
		}

		http.newCall(authed(url).get().build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("GIM Tracker request failed: {}", url, e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (r.isSuccessful() && r.body() != null)
					{
						JsonObject json = gson.fromJson(r.body().string(), JsonObject.class);
						onSuccess.accept(json);
					}
				}
				catch (Exception e)
				{
					log.debug("GIM Tracker failed parsing response", e);
				}
			}
		});
	}
}

package com.gimtracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("gimtracker")
public interface GimTrackerConfig extends Config
{
	@ConfigItem(
		keyName = "serverUrl",
		name = "Server URL",
		description = "Base URL of your group's GIM Tracker server, e.g. https://gim.example.com",
		position = 1
	)
	default String serverUrl()
	{
		return "http://localhost:3000";
	}

	@ConfigItem(
		keyName = "groupToken",
		name = "Group token",
		description = "Shared secret for your group. Everyone in the group uses the same token.",
		secret = true,
		position = 2
	)
	default String groupToken()
	{
		return "";
	}

	@ConfigItem(
		keyName = "shareGroupStorage",
		name = "Share group storage",
		description = "Send the shared Group Ironman storage to the server when you open it",
		position = 3
	)
	default boolean shareGroupStorage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "shareBank",
		name = "Share personal bank",
		description = "Send your own bank contents so groupmates can search who has an item",
		position = 4
	)
	default boolean shareBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "shareEvents",
		name = "Share milestones",
		description = "Send level ups, quest completions, collection log slots, valuable drops and deaths",
		position = 5
	)
	default boolean shareEvents()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sharePresence",
		name = "Share online status",
		description = "Let your group see when you are online and what world you are on",
		position = 6
	)
	default boolean sharePresence()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bridgeChat",
		name = "Discord chat bridge",
		description = "Relay your group's GIM chat to a Discord channel and show Discord replies in your chatbox",
		position = 7
	)
	default boolean bridgeChat()
	{
		return true;
	}
}

package com.gimtracker;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntConsumer;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
