/**
 * Right sidebar panel with named tabs: Group (storage, members, activity),
 * Board (to-do, goals), Items (requests, bank search) and Runs (timers, XP race).
 */
public class GimTrackerPanel extends PluginPanel
{
	private static final Color CARD_BG = ColorScheme.DARKER_GRAY_COLOR;
	private static final Color ONLINE_GREEN = new Color(106, 190, 89);
	private static final Color OFFLINE_GRAY = new Color(110, 110, 110);
	private static final Color GOLD = new Color(255, 200, 70);
	private static final Color RED = new Color(230, 90, 90);
	private static final Color[] URGENCY_COLORS = {ONLINE_GREEN, GOLD, RED};
	private static final String[] URGENCY_NAMES = {"Low", "Normal", "High"};

	private final ApiClient api;
	private final ItemManager itemManager;
	private final Supplier<String> playerName;
	private final IntConsumer hopToWorld;

	private final JLabel storageValueLabel = new JLabel("--");
	private final JLabel storageItemsLabel = new JLabel("--");
	private final JLabel onlineCountLabel = new JLabel("--");
	private final JPanel membersPanel = new JPanel();
	private final JPanel timersPanel = new JPanel();
	private final JPanel tasksPanel = new JPanel();
	private final JPanel goalsPanel = new JPanel();
	private final JPanel requestsPanel = new JPanel();
	private final JPanel racePanel = new JPanel();
	private final JPanel activityPanel = new JPanel();
	private final JPanel resultsPanel = new JPanel();
	private final JTextField taskField = new JTextField();
	private final JTextField goalField = new JTextField();
	private final JTextField raceField = new JTextField();
	private final IconTextField searchField = new IconTextField();

	// New request builder state
	private final IconTextField itemSearchField = new IconTextField();
	private final JPanel itemResultsPanel = new JPanel();
	private final JLabel selectedItemLabel = new JLabel("No item selected");
	private final JTextField qtyField = new JTextField("1");
	private final JButton[] urgencyButtons = new JButton[3];
	private final JButton taskUrgencyButton = new JButton("\u25CF");
	private int selectedItemId;
	private String selectedItemName;
	private int requestUrgency = 1;
	private int taskUrgency = 1;

	GimTrackerPanel(ApiClient api, ItemManager itemManager, Supplier<String> playerName, IntConsumer hopToWorld)
	{
		this.api = api;
		this.itemManager = itemManager;
		this.playerName = playerName;
		this.hopToWorld = hopToWorld;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(8, 8, 8, 8));

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		content.add(buildHeader());
		content.add(Box.createVerticalStrut(8));

		JPanel display = new JPanel(new BorderLayout());
		display.setBackground(ColorScheme.DARK_GRAY_COLOR);
		display.setAlignmentX(JComponent.LEFT_ALIGNMENT);

		MaterialTabGroup tabGroup = new MaterialTabGroup(display);
		tabGroup.setLayout(new GridLayout(1, 4, 2, 0));
		tabGroup.setBorder(new EmptyBorder(0, 0, 8, 0));
		tabGroup.setAlignmentX(JComponent.LEFT_ALIGNMENT);

		MaterialTab groupTab = tab("group", "Group: members, storage and activity", tabGroup, buildGroupTab());
		tabGroup.addTab(groupTab);
		tabGroup.addTab(tab("board", "Board: to-do list and goals", tabGroup, buildBoardTab()));
		tabGroup.addTab(tab("items", "Items: requests and bank search", tabGroup, buildItemsTab()));
		tabGroup.addTab(tab("runs", "Runs: timers and XP races", tabGroup, buildRunsTab()));
		tabGroup.select(groupTab);

		content.add(tabGroup);
		content.add(display);

		add(content, BorderLayout.NORTH);
	}

	private static JPanel tabPanel()
	{
		JPanel tab = new JPanel();
		tab.setLayout(new BoxLayout(tab, BoxLayout.Y_AXIS));
		tab.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return tab;
	}

	private static MaterialTab tab(String iconType, String tooltip, MaterialTabGroup group, JComponent content)
	{
		MaterialTab tab = new MaterialTab(tabIcon(iconType), group, content);
		tab.setToolTipText(tooltip);
		tab.setHorizontalAlignment(SwingConstants.CENTER);
		return tab;
	}

	/** Small hand-drawn tab icons so we don't need binary resources. */
	private static ImageIcon tabIcon(String type)
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		g.setStroke(new BasicStroke(1.4f));
		switch (type)
		{
			case "group":
				// Two people: one behind, one in front
				g.fillOval(9, 2, 6, 6);
				g.fillArc(7, 9, 9, 9, 0, 180);
				g.setColor(Color.WHITE);
				g.fillOval(2, 3, 6, 6);
				g.fillArc(0, 10, 9, 9, 0, 180);
				break;
			case "board":
				// Clipboard with lines and a green tick
				g.drawRoundRect(3, 1, 10, 13, 3, 3);
				g.drawLine(6, 5, 11, 5);
				g.drawLine(6, 8, 11, 8);
				g.setColor(ONLINE_GREEN);
				g.drawLine(5, 11, 7, 13);
				g.drawLine(7, 13, 11, 9);
				break;
			case "items":
				// Shopping bag with a handle
				g.drawRoundRect(3, 5, 10, 9, 3, 3);
				g.drawArc(5, 1, 6, 7, 0, 180);
				break;
			case "runs":
				// Clock face with hands
				g.drawOval(2, 2, 12, 12);
				g.drawLine(8, 8, 8, 4);
				g.drawLine(8, 8, 11, 10);
				break;
			default:
				break;
		}
		g.dispose();
		return new ImageIcon(img);
	}

	private JPanel buildGroupTab()
	{
		JPanel tab = tabPanel();
		tab.add(buildStorageCard());
		tab.add(Box.createVerticalStrut(10));

		tab.add(sectionHeader("MEMBERS"));
		membersPanel.setLayout(new BoxLayout(membersPanel, BoxLayout.Y_AXIS));
		membersPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		membersPanel.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		membersPanel.add(mutedRow("Waiting for the server..."));
		tab.add(membersPanel);
		tab.add(Box.createVerticalStrut(10));

		tab.add(sectionHeader("RECENT ACTIVITY"));
		activityPanel.setLayout(new BoxLayout(activityPanel, BoxLayout.Y_AXIS));
		activityPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		activityPanel.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		activityPanel.add(mutedRow("Waiting for the server..."));
		tab.add(activityPanel);
		return tab;
	}

	private JPanel buildBoardTab()
	{
		JPanel tab = tabPanel();
		tab.add(sectionHeader("GROUP TO-DO"));
		tasksPanel.setLayout(new BoxLayout(tasksPanel, BoxLayout.Y_AXIS));
		tasksPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		tasksPanel.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		tab.add(tasksPanel);
		tab.add(Box.createVerticalStrut(4));

		JPanel addRow = new JPanel(new BorderLayout(4, 0));
		addRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		addRow.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		addRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		styleInput(taskField, "Add a task, press Enter");
		taskField.addActionListener(e -> addTask());
		addRow.add(taskField, BorderLayout.CENTER);

		taskUrgencyButton.setFont(FontManager.getRunescapeBoldFont());
		taskUrgencyButton.setMargin(new Insets(1, 6, 1, 6));
		taskUrgencyButton.setFocusPainted(false);
		taskUrgencyButton.setBackground(CARD_BG);
		taskUrgencyButton.addActionListener(e ->
		{
			taskUrgency = (taskUrgency + 1) % 3;
			refreshTaskUrgencyButton();
		});
		refreshTaskUrgencyButton();
		addRow.add(taskUrgencyButton, BorderLayout.EAST);
		tab.add(addRow);
		tab.add(Box.createVerticalStrut(10));

		tab.add(sectionHeader("GROUP GOALS"));
		goalsPanel.setLayout(new BoxLayout(goalsPanel, BoxLayout.Y_AXIS));
		goalsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		goalsPanel.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		tab.add(goalsPanel);
		tab.add(Box.createVerticalStrut(4));
		styleInput(goalField, "e.g. Vial of water x1000 - progress tracks group storage");
		goalField.addActionListener(e -> addGoal());
		tab.add(goalField);
		return tab;
	}

	private JPanel buildItemsTab()
	{
		JPanel tab = tabPanel();
		tab.add(sectionHeader("ITEM REQUESTS"));
		requestsPanel.setLayout(new BoxLayout(requestsPanel, BoxLayout.Y_AXIS));
		requestsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		requestsPanel.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		tab.add(requestsPanel);
		tab.add(Box.createVerticalStrut(10));

		tab.add(sectionHeader("NEW REQUEST"));
		itemSearchField.setIcon(IconTextField.Icon.SEARCH);
		itemSearchField.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 30));
		itemSearchField.setBackground(CARD_BG);
		itemSearchField.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		itemSearchField.setToolTipText("Search any OSRS item, press Enter");
		itemSearchField.addActionListener(e -> searchItems());
		itemSearchField.addClearListener(this::clearItemSearch);
		itemSearchField.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		tab.add(itemSearchField);
		tab.add(Box.createVerticalStrut(4));

		itemResultsPanel.setLayout(new BoxLayout(itemResultsPanel, BoxLayout.Y_AXIS));
		itemResultsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		itemResultsPanel.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		tab.add(itemResultsPanel);
		tab.add(Box.createVerticalStrut(4));

		tab.add(buildRequestBuilder());
		tab.add(Box.createVerticalStrut(10));

		tab.add(sectionHeader("BANK SEARCH"));
		searchField.setIcon(IconTextField.Icon.SEARCH);
		searchField.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 30));
		searchField.setBackground(CARD_BG);
		searchField.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchField.addActionListener(e -> runSearch());
		searchField.addClearListener(this::clearSearch);
		searchField.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		tab.add(searchField);
		tab.add(Box.createVerticalStrut(6));

		resultsPanel.setLayout(new BoxLayout(resultsPanel, BoxLayout.Y_AXIS));
		resultsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		resultsPanel.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		tab.add(resultsPanel);
		return tab;
	}

	/** Card with the selected item, quantity presets, urgency picker and submit button. */
	private JPanel buildRequestBuilder()
	{
		JPanel builder = card();
		builder.setLayout(new BoxLayout(builder, BoxLayout.Y_AXIS));

		selectedItemLabel.setFont(FontManager.getRunescapeFont());
		selectedItemLabel.setForeground(OFFLINE_GRAY);
		selectedItemLabel.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		builder.add(selectedItemLabel);
		builder.add(Box.createVerticalStrut(8));

		// Quantity with quick presets
		JPanel qtyRow = new JPanel(new BorderLayout(6, 0));
		qtyRow.setBackground(CARD_BG);
		qtyRow.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		qtyRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));

		styleInput(qtyField, "Amount - supports 500, 5k, 1.5m");
		qtyField.setBackground(ColorScheme.DARK_GRAY_COLOR);
		qtyRow.add(qtyField, BorderLayout.CENTER);

		JPanel quick = new JPanel(new GridLayout(1, 4, 3, 0));
		quick.setBackground(CARD_BG);
		for (String preset : new String[]{"1", "10", "100", "1k"})
		{
			JButton b = smallButton(preset, "Set quantity to " + preset);
			b.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			b.addActionListener(e -> qtyField.setText(preset));
			quick.add(b);
		}
		qtyRow.add(quick, BorderLayout.EAST);
		builder.add(qtyRow);
		builder.add(Box.createVerticalStrut(8));

		// Urgency picker
		JPanel urgencyRow = new JPanel(new GridLayout(1, 3, 4, 0));
		urgencyRow.setBackground(CARD_BG);
		urgencyRow.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		urgencyRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		for (int i = 0; i < 3; i++)
		{
			final int level = i;
			JButton b = new JButton(URGENCY_NAMES[i]);
			b.setFont(FontManager.getRunescapeSmallFont());
			b.setMargin(new Insets(2, 4, 2, 4));
			b.setFocusPainted(false);
			b.addActionListener(e ->
			{
				requestUrgency = level;
				refreshUrgencyButtons();
			});
			urgencyButtons[i] = b;
			urgencyRow.add(b);
		}
		refreshUrgencyButtons();
		builder.add(urgencyRow);
		builder.add(Box.createVerticalStrut(10));

		JButton submit = new JButton("Request item");
		submit.setFont(FontManager.getRunescapeBoldFont());
		submit.setFocusPainted(false);
		submit.setBackground(ColorScheme.BRAND_ORANGE);
		submit.setForeground(Color.BLACK);
		submit.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		submit.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		submit.addActionListener(e -> submitRequest());
		builder.add(submit);

		return builder;
	}

	private void refreshUrgencyButtons()
	{
		for (int i = 0; i < 3; i++)
		{
			boolean selected = i == requestUrgency;
			urgencyButtons[i].setBackground(selected ? URGENCY_COLORS[i] : ColorScheme.DARK_GRAY_COLOR);
			urgencyButtons[i].setForeground(selected ? Color.BLACK : URGENCY_COLORS[i]);
		}
	}

	private void refreshTaskUrgencyButton()
	{
		taskUrgencyButton.setForeground(URGENCY_COLORS[taskUrgency]);
		taskUrgencyButton.setToolTipText("Urgency: " + URGENCY_NAMES[taskUrgency] + " (click to change)");
	}

	private void searchItems()
	{
		String query = itemSearchField.getText().trim();
		itemResultsPanel.removeAll();
		if (query.length() >= 2)
		{
			List<ItemPrice> results = itemManager.search(query);
			if (results.isEmpty())
			{
				itemResultsPanel.add(mutedRow("No matching items"));
			}
			int count = 0;
			for (ItemPrice item : results)
			{
				if (count++ >= 8)
				{
					break;
				}
				itemResultsPanel.add(itemResultRow(item));
				itemResultsPanel.add(Box.createVerticalStrut(2));
			}
		}
		itemResultsPanel.revalidate();
		itemResultsPanel.repaint();
	}

	private void clearItemSearch()
	{
		SwingUtilities.invokeLater(() ->
		{
			itemResultsPanel.removeAll();
			itemResultsPanel.revalidate();
			itemResultsPanel.repaint();
		});
	}

	private JPanel itemResultRow(ItemPrice item)
	{
		JPanel rowPanel = card();
		rowPanel.setLayout(new BorderLayout(8, 0));
		rowPanel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		rowPanel.setToolTipText("Select " + item.getName());

		JLabel iconLabel = new JLabel();
		iconLabel.setPreferredSize(new Dimension(26, 26));
		itemManager.getImage(item.getId()).addTo(iconLabel);
		rowPanel.add(iconLabel, BorderLayout.WEST);

		JLabel name = new JLabel(item.getName());
		name.setFont(FontManager.getRunescapeFont());
		name.setForeground(Color.WHITE);
		rowPanel.add(name, BorderLayout.CENTER);

