	private void submitRequest()
	{
		String item = selectedItemName;
		if (item == null || item.isEmpty())
		{
			// No picked item: fall back to whatever was typed in the search box
			item = itemSearchField.getText().trim();
			if (item.isEmpty())
			{
				return;
			}
		}

		Map<String, Object> body = new HashMap<>();
		body.put("item", item);
		if (selectedItemId > 0)
		{
			body.put("itemId", selectedItemId);
		}
		body.put("qty", parseQty(qtyField.getText()));
		body.put("urgency", requestUrgency);
		body.put("member", playerName.get());
		api.post("api/requests", body, this::refresh);

		// Reset the builder
		selectedItemId = 0;
		selectedItemName = null;
		selectedItemLabel.setText("No item selected");
		selectedItemLabel.setForeground(OFFLINE_GRAY);
		selectedItemLabel.setIcon(null);
		qtyField.setText("1");
		itemSearchField.setText("");
	}

	private static long parseQty(String text)
	{
		String s = text.trim().toLowerCase().replace(",", "");
		long mult = 1;
		if (s.endsWith("k"))
		{
			mult = 1_000;
			s = s.substring(0, s.length() - 1);
		}
		else if (s.endsWith("m"))
		{
			mult = 1_000_000;
			s = s.substring(0, s.length() - 1);
		}
		try
		{
			return Math.max(1, (long) (Double.parseDouble(s) * mult));
		}
		catch (NumberFormatException e)
		{
			return 1;
		}
	}

