	private void showGroup(JsonObject group)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (group.has("storage"))
			{
				JsonObject storage = group.getAsJsonObject("storage");
				storageValueLabel.setText(QuantityFormatter.quantityToStackSize(storage.get("totalValue").getAsLong()) + " gp");
				storageItemsLabel.setText(QuantityFormatter.formatNumber(storage.get("distinctItems").getAsLong()));
			}

			membersPanel.removeAll();
			int totalMembers = 0;
			int onlineMembers = 0;
			if (group.has("members"))
			{
				for (JsonElement el : group.getAsJsonArray("members"))
				{
					JsonObject member = el.getAsJsonObject();
					totalMembers++;
					if (member.get("online").getAsBoolean())
					{
						onlineMembers++;
					}
					membersPanel.add(memberCard(member));
					membersPanel.add(Box.createVerticalStrut(4));
				}
			}
			onlineCountLabel.setText(onlineMembers + "/" + totalMembers + " online");
			onlineCountLabel.setIcon(new StatusDot(onlineMembers > 0 ? ONLINE_GREEN : OFFLINE_GRAY));

			timersPanel.removeAll();
			if (group.has("timers"))
			{
				for (JsonElement el : group.getAsJsonArray("timers"))
				{
					timersPanel.add(timerRow(el.getAsJsonObject()));
					timersPanel.add(Box.createVerticalStrut(3));
				}
			}

			tasksPanel.removeAll();
			JsonArray tasks = group.has("tasks") ? group.getAsJsonArray("tasks") : new JsonArray();
			if (tasks.size() == 0)
			{
				tasksPanel.add(mutedRow("Nothing on the list"));
			}
			for (JsonElement el : tasks)
			{
				tasksPanel.add(taskRow(el.getAsJsonObject()));
				tasksPanel.add(Box.createVerticalStrut(3));
			}

			requestsPanel.removeAll();
			JsonArray requests = group.has("requests") ? group.getAsJsonArray("requests") : new JsonArray();
			if (requests.size() == 0)
			{
				requestsPanel.add(mutedRow("No open requests"));
			}
			for (JsonElement el : requests)
			{
				requestsPanel.add(requestRow(el.getAsJsonObject()));
				requestsPanel.add(Box.createVerticalStrut(3));
			}

			goalsPanel.removeAll();
			JsonArray goals = group.has("goals") ? group.getAsJsonArray("goals") : new JsonArray();
			if (goals.size() == 0)
			{
				goalsPanel.add(mutedRow("No goals set"));
			}
			for (JsonElement el : goals)
			{
				goalsPanel.add(goalRow(el.getAsJsonObject()));
				goalsPanel.add(Box.createVerticalStrut(3));
			}

			racePanel.removeAll();
			boolean raceRunning = group.has("race") && group.get("race").isJsonObject();
			raceField.setVisible(!raceRunning);
			if (raceRunning)
			{
				renderRace(group.getAsJsonObject("race"));
			}
			else
			{
				racePanel.add(mutedRow("No race running - start one below"));
			}

			activityPanel.removeAll();
			JsonArray activity = group.has("activity") ? group.getAsJsonArray("activity") : new JsonArray();
			if (activity.size() == 0)
			{
				activityPanel.add(mutedRow("Nothing yet - go make some progress!"));
			}
			for (JsonElement el : activity)
			{
				activityPanel.add(activityRow(el.getAsJsonObject()));
				activityPanel.add(Box.createVerticalStrut(3));
			}

			revalidate();
			repaint();
		});
	}

	private JPanel timerRow(JsonObject timer)
	{
		JPanel rowPanel = card();
		rowPanel.setLayout(new BorderLayout(6, 0));

		JLabel name = new JLabel(timer.get("label").getAsString());
		name.setFont(FontManager.getRunescapeFont());
		name.setForeground(Color.WHITE);
		rowPanel.add(name, BorderLayout.CENTER);

		long readyAt = timer.get("readyAt").getAsLong();
		long remaining = readyAt - System.currentTimeMillis();
		JLabel status = new JLabel(remaining <= 0 ? "Ready" : "in " + timeUntil(remaining));
		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(remaining <= 0 ? ONLINE_GREEN : remaining <= 10 * 60_000 ? GOLD : OFFLINE_GRAY);
		if (!timer.get("resetBy").isJsonNull())
		{
			status.setToolTipText("Last done by " + timer.get("resetBy").getAsString());
		}

		JPanel east = new JPanel(new BorderLayout(6, 0));
		east.setBackground(CARD_BG);
		east.add(status, BorderLayout.CENTER);

		String timerName = timer.get("name").getAsString();
		JButton done = smallButton("\u2713", "Mark this run as just done");
		done.addActionListener(e ->
		{
			Map<String, Object> body = new HashMap<>();
			body.put("member", playerName.get());
			api.post("api/timers/" + timerName + "/reset", body, this::refresh);
		});
		east.add(done, BorderLayout.EAST);

		rowPanel.add(east, BorderLayout.EAST);
		return rowPanel;
	}

	private JPanel taskRow(JsonObject task)
	{
		JPanel rowPanel = card();
		rowPanel.setLayout(new BorderLayout(6, 0));

		boolean done = task.has("done") && task.get("done").getAsBoolean();
		int urgency = task.has("urgency") ? Math.max(0, Math.min(2, task.get("urgency").getAsInt())) : 1;
		urgencyStripe(rowPanel, done ? OFFLINE_GRAY : URGENCY_COLORS[urgency]);

		JCheckBox tick = new JCheckBox();
		tick.setSelected(done);
		tick.setBackground(CARD_BG);
		tick.setFocusPainted(false);
		rowPanel.add(tick, BorderLayout.WEST);

		JPanel textPanel = new JPanel();
		textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
		textPanel.setBackground(CARD_BG);

		String taskText = escapeHtml(task.get("text").getAsString());
		JLabel text = new JLabel("<html>" + (done ? "<strike>" + taskText + "</strike>" : taskText) + "</html>");
		text.setFont(FontManager.getRunescapeFont());
		text.setForeground(done ? OFFLINE_GRAY : Color.WHITE);
		text.setToolTipText("Added by " + task.get("createdBy").getAsString()
			+ " - " + URGENCY_NAMES[urgency] + " urgency");
		textPanel.add(text);

		if (done)
		{
			tick.setEnabled(false);
			String doneBy = task.get("doneBy").isJsonNull() ? "unknown" : task.get("doneBy").getAsString();
			JLabel who = new JLabel("done by " + doneBy);
			who.setFont(FontManager.getRunescapeSmallFont());
			who.setForeground(ONLINE_GREEN);
			textPanel.add(who);
		}
		else
		{
			int id = task.get("id").getAsInt();
			tick.setToolTipText("Tick off this task");
			tick.addActionListener(e ->
			{
				tick.setEnabled(false);
				Map<String, Object> body = new HashMap<>();
				body.put("member", playerName.get());
				api.post("api/tasks/" + id + "/done", body, this::refresh);
			});
		}

		rowPanel.add(textPanel, BorderLayout.CENTER);
		return rowPanel;
	}

	private JPanel requestRow(JsonObject request)
	{
		JPanel rowPanel = card();
		rowPanel.setLayout(new BorderLayout(6, 4));

		int urgency = request.has("urgency") ? Math.max(0, Math.min(2, request.get("urgency").getAsInt())) : 1;
		urgencyStripe(rowPanel, URGENCY_COLORS[urgency]);

		if (request.has("itemId") && !request.get("itemId").isJsonNull())
		{
			JLabel iconLabel = new JLabel();
			iconLabel.setPreferredSize(new Dimension(26, 26));
			itemManager.getImage(request.get("itemId").getAsInt()).addTo(iconLabel);
			rowPanel.add(iconLabel, BorderLayout.WEST);
		}

		JPanel textPanel = new JPanel();
		textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
		textPanel.setBackground(CARD_BG);

		long qty = request.get("qty").getAsLong();
		long progress = request.has("progress") ? request.get("progress").getAsLong() : 0;
		JLabel name = new JLabel("<html>" + escapeHtml(request.get("item").getAsString()) + "</html>");
		name.setFont(FontManager.getRunescapeFont());
		name.setForeground(Color.WHITE);
		name.setToolTipText(URGENCY_NAMES[urgency] + " urgency");
		textPanel.add(name);

		JLabel who = new JLabel("for " + request.get("requestedBy").getAsString());
		who.setFont(FontManager.getRunescapeSmallFont());
		who.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		textPanel.add(who);

		rowPanel.add(textPanel, BorderLayout.CENTER);

		int id = request.get("id").getAsInt();

		JPanel buttons = new JPanel(new GridLayout(1, 2, 3, 0));
		buttons.setBackground(CARD_BG);

		// Shopping list: tick off part of the request
		JButton plus = smallButton("+", "Add progress (bought some)");
		plus.setForeground(GOLD);
		plus.addActionListener(e ->
		{
			String input = JOptionPane.showInputDialog(this,
				"How many " + request.get("item").getAsString() + " did you get?",
				Long.toString(qty - progress));
			if (input == null)
			{
				return;
			}
			try
			{
				long amount = Long.parseLong(input.trim().replace(",", ""));
				if (amount > 0)
				{
					Map<String, Object> body = new HashMap<>();
					body.put("member", playerName.get());
					body.put("amount", amount);
					api.post("api/requests/" + id + "/progress", body, this::refresh);
				}
			}
			catch (NumberFormatException ignored)
			{
				// not a number, ignore
			}
		});
		buttons.add(plus);

		JButton done = smallButton("\u2713", "Mark as fully fulfilled");
		done.addActionListener(e ->
		{
			Map<String, Object> body = new HashMap<>();
			body.put("member", playerName.get());
			api.post("api/requests/" + id + "/fulfill", body, this::refresh);
		});
		buttons.add(done);

		rowPanel.add(buttons, BorderLayout.EAST);

		if (qty > 1)
		{
			rowPanel.add(new Bar(progress, qty), BorderLayout.SOUTH);
		}

		return rowPanel;
	}

	private JPanel goalRow(JsonObject goal)
	{
		JPanel rowPanel = card();
		rowPanel.setLayout(new BorderLayout(6, 4));

		long target = goal.get("target").getAsLong();
		long progress = goal.get("progress").getAsLong();

		JLabel name = new JLabel("<html>" + escapeHtml(goal.get("item").getAsString()) + "</html>");
		name.setFont(FontManager.getRunescapeFont());
		name.setForeground(progress >= target ? ONLINE_GREEN : Color.WHITE);
		name.setToolTipText("Added by " + goal.get("createdBy").getAsString()
			+ " - progress tracks group storage");
		rowPanel.add(name, BorderLayout.CENTER);

		int id = goal.get("id").getAsInt();
		JButton remove = smallButton("x", "Remove goal");
		remove.setForeground(OFFLINE_GRAY);
		remove.addActionListener(e ->
			api.post("api/goals/" + id + "/remove", new HashMap<String, Object>(), this::refresh));
		rowPanel.add(remove, BorderLayout.EAST);

		rowPanel.add(new Bar(progress, target), BorderLayout.SOUTH);
		return rowPanel;
	}

	private void renderRace(JsonObject race)
	{
		JPanel headerPanel = card();
		headerPanel.setLayout(new BorderLayout(6, 0));

		JLabel skill = new JLabel(race.get("skill").getAsString() + " race");
		skill.setFont(FontManager.getRunescapeBoldFont());
		skill.setForeground(GOLD);
		headerPanel.add(skill, BorderLayout.CENTER);

		long endsAt = race.get("endsAt").getAsLong();
		JLabel ends = new JLabel("ends in " + timeUntil(Math.max(0, endsAt - System.currentTimeMillis())));
		ends.setFont(FontManager.getRunescapeSmallFont());
		ends.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		headerPanel.add(ends, BorderLayout.EAST);

		racePanel.add(headerPanel);
		racePanel.add(Box.createVerticalStrut(3));

		JsonArray standings = race.getAsJsonArray("standings");
		if (standings == null || standings.size() == 0)
		{
			racePanel.add(mutedRow("No XP tracked yet - go train!"));
			return;
		}

		int rank = 1;
		for (JsonElement el : standings)
		{
			JsonObject entry = el.getAsJsonObject();
			JPanel rowPanel = card();
			rowPanel.setLayout(new BorderLayout(6, 0));

			JLabel place = new JLabel(rank == 1 ? "\u2605" : Integer.toString(rank));
			place.setFont(FontManager.getRunescapeSmallFont());
			place.setForeground(rank == 1 ? GOLD : OFFLINE_GRAY);
			place.setPreferredSize(new Dimension(14, 16));
			rowPanel.add(place, BorderLayout.WEST);

			JLabel name = new JLabel(entry.get("member").getAsString());
			name.setFont(FontManager.getRunescapeFont());
			name.setForeground(rank == 1 ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
			rowPanel.add(name, BorderLayout.CENTER);

			JLabel gained = new JLabel(QuantityFormatter.quantityToStackSize(entry.get("gained").getAsLong()) + " xp");
			gained.setFont(FontManager.getRunescapeSmallFont());
			gained.setForeground(ONLINE_GREEN);
			rowPanel.add(gained, BorderLayout.EAST);

			racePanel.add(rowPanel);
			racePanel.add(Box.createVerticalStrut(3));
			rank++;
		}
	}

	private void addTask()
	{
		String text = taskField.getText().trim();
		if (text.isEmpty())
		{
			return;
		}
		taskField.setText("");
		Map<String, Object> body = new HashMap<>();
		body.put("text", text);
		body.put("urgency", taskUrgency);
		body.put("member", playerName.get());
		api.post("api/tasks", body, this::refresh);
	}

	private void addGoal()
	{
		String text = goalField.getText().trim();
		if (text.isEmpty())
		{
			return;
		}
		goalField.setText("");

		// Same "item xTarget" format as requests
		String item = text;
		long target = 1;
		int split = text.toLowerCase().lastIndexOf(" x");
		if (split > 0)
		{
			try
			{
				target = Long.parseLong(text.substring(split + 2).trim().replace(",", ""));
				item = text.substring(0, split).trim();
			}
			catch (NumberFormatException ignored)
			{
				// no target suffix
			}
		}

		Map<String, Object> body = new HashMap<>();
		body.put("item", item);
		body.put("target", target);
		body.put("member", playerName.get());
		api.post("api/goals", body, this::refresh);
	}

	private void startRace()
	{
		String text = raceField.getText().trim();
		if (text.isEmpty())
		{
			return;
		}
		raceField.setText("");

		// "skill days", days optional (defaults to 7)
		String skill = text;
		int days = 7;
		int split = text.lastIndexOf(' ');
		if (split > 0)
		{
			try
			{
				days = Integer.parseInt(text.substring(split + 1).trim());
				skill = text.substring(0, split).trim();
			}
			catch (NumberFormatException ignored)
			{
				// no day count given
			}
		}

		Map<String, Object> body = new HashMap<>();
		body.put("skill", skill);
		body.put("days", days);
		body.put("member", playerName.get());
		api.post("api/race", body, this::refresh);
	}

