			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				button.setBackground(ColorScheme.DARK_GRAY_COLOR);
			}
		});
		return button;
	}

	/** Compact progress bar with a "current/target" label. */
	private static class Bar extends JComponent
	{
		private final long value;
		private final long max;

		Bar(long value, long max)
		{
			this.value = value;
			this.max = Math.max(1, max);
			setPreferredSize(new Dimension(100, 14));
			setMinimumSize(new Dimension(40, 14));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			int w = getWidth();
			int h = getHeight();
			g.setColor(ColorScheme.DARK_GRAY_COLOR);
			g.fillRect(0, 0, w, h);

			int fill = (int) Math.min(w, value * w / max);
			g.setColor(value >= max ? ONLINE_GREEN : ColorScheme.BRAND_ORANGE);
			g.fillRect(0, 0, fill, h);

			String label = QuantityFormatter.quantityToStackSize(value)
				+ " / " + QuantityFormatter.quantityToStackSize(max);
			g.setFont(FontManager.getRunescapeSmallFont());
			int tw = g.getFontMetrics().stringWidth(label);
			g.setColor(Color.WHITE);
			g.drawString(label, (w - tw) / 2, h - 3);
		}
	}

	private static void styleInput(JTextField field, String tooltip)
	{
		field.setToolTipText(tooltip);
		field.setFont(FontManager.getRunescapeSmallFont());
		field.setBackground(CARD_BG);
		field.setForeground(Color.WHITE);
		field.setCaretColor(Color.WHITE);
		field.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(4, 6, 4, 6)));
		field.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		field.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		field.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusGained(FocusEvent e)
			{
				field.setBorder(BorderFactory.createCompoundBorder(
					BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE),
					new EmptyBorder(4, 6, 4, 6)));
			}

			@Override
			public void focusLost(FocusEvent e)
			{
				field.setBorder(BorderFactory.createCompoundBorder(
					BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
					new EmptyBorder(4, 6, 4, 6)));
			}
		});
	}

	private static String timeUntil(long millis)
	{
		long minutes = millis / 60_000;
		if (minutes < 60)
		{
			return Math.max(1, minutes) + "m";
		}
		if (minutes < 1440)
		{
			return (minutes / 60) + "h " + (minutes % 60) + "m";
		}
		return (minutes / 1440) + "d " + (minutes % 1440 / 60) + "h";
	}

	private JPanel memberCard(JsonObject member)
	{
		boolean online = member.get("online").getAsBoolean();

		JPanel cardPanel = card();
		cardPanel.setLayout(new BorderLayout(8, 0));

		JLabel dot = new JLabel(new StatusDot(online ? ONLINE_GREEN : OFFLINE_GRAY));
		cardPanel.add(dot, BorderLayout.WEST);

		String memberName = member.get("name").getAsString();
		boolean isSelf = memberName.equals(playerName.get());
		JLabel name = new JLabel(memberName);
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(online ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		if (isSelf)
		{
			name.setForeground(GOLD);
			name.setToolTipText("This is you");
		}
		cardPanel.add(name, BorderLayout.CENTER);

		int memberWorld = member.get("world").getAsInt();
		String detail = online
			? "W" + memberWorld
			: "seen " + timeAgo(member.get("lastSeen").getAsLong());
		JLabel status = new JLabel(detail);
		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(online ? ONLINE_GREEN : OFFLINE_GRAY);
		cardPanel.add(status, BorderLayout.EAST);

		// Click an online teammate to hop to their world
		if (online && memberWorld > 0 && !memberName.equals(playerName.get()))
		{
			cardPanel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			cardPanel.setToolTipText("Click to hop to World " + memberWorld);
			cardPanel.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					hopToWorld.accept(memberWorld);
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					cardPanel.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					cardPanel.setBackground(CARD_BG);
				}
			});
		}

		return cardPanel;
	}

	private JPanel activityRow(JsonObject activity)
	{
		JPanel rowPanel = card();
		rowPanel.setLayout(new BorderLayout(6, 0));

		String type = activity.get("type").getAsString();
		JLabel badge = new JLabel(badgeText(type));
		badge.setFont(FontManager.getRunescapeSmallFont());
		badge.setForeground(badgeColor(type));
		badge.setPreferredSize(new Dimension(38, 16));
		rowPanel.add(badge, BorderLayout.WEST);

		JLabel text = new JLabel("<html>" + escapeHtml(activity.get("member").getAsString()
			+ " " + activity.get("text").getAsString()) + "</html>");
		text.setFont(FontManager.getRunescapeSmallFont());
		text.setForeground(Color.WHITE);
		rowPanel.add(text, BorderLayout.CENTER);

		JLabel time = new JLabel(timeAgo(activity.get("timestamp").getAsLong()));
		time.setFont(FontManager.getRunescapeSmallFont());
		time.setForeground(OFFLINE_GRAY);
		time.setVerticalAlignment(SwingConstants.TOP);
		rowPanel.add(time, BorderLayout.EAST);

		return rowPanel;
	}

	private void showSearchResults(JsonObject response)
	{
		SwingUtilities.invokeLater(() ->
		{
			resultsPanel.removeAll();
			JsonArray items = response.getAsJsonArray("items");
			if (items == null || items.size() == 0)
			{
				resultsPanel.add(mutedRow("No matches"));
			}
			else
			{
				for (JsonElement el : items)
				{
					resultsPanel.add(itemRow(el.getAsJsonObject()));
					resultsPanel.add(Box.createVerticalStrut(3));
				}
			}
			resultsPanel.revalidate();
			resultsPanel.repaint();
		});
	}

	private JPanel itemRow(JsonObject item)
	{
		JPanel rowPanel = card();
		rowPanel.setLayout(new BorderLayout(8, 0));

		int qty = item.get("qty").getAsInt();

		if (item.has("id"))
		{
			JLabel iconLabel = new JLabel();
			iconLabel.setPreferredSize(new Dimension(32, 32));
			AsyncBufferedImage itemImage = itemManager.getImage(item.get("id").getAsInt(), qty, qty > 1);
			itemImage.addTo(iconLabel);
			rowPanel.add(iconLabel, BorderLayout.WEST);
		}

		JPanel textPanel = new JPanel();
		textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
		textPanel.setBackground(CARD_BG);

		JLabel name = new JLabel(item.get("name").getAsString());
		name.setFont(FontManager.getRunescapeFont());
		name.setForeground(Color.WHITE);
		textPanel.add(name);

		String where = item.has("owner") ? item.get("owner").getAsString() : "";
		JLabel meta = new JLabel("x" + QuantityFormatter.quantityToStackSize(qty)
			+ (where.isEmpty() ? "" : "  \u00B7  " + where));
		meta.setFont(FontManager.getRunescapeSmallFont());
		meta.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		textPanel.add(meta);

		rowPanel.add(textPanel, BorderLayout.CENTER);

		long value = (long) qty * item.get("price").getAsLong();
		JLabel valueLabel = new JLabel(QuantityFormatter.quantityToStackSize(value));
		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		valueLabel.setForeground(GOLD);
		rowPanel.add(valueLabel, BorderLayout.EAST);

		return rowPanel;
	}

	private static JPanel card()
	{
		return new CardPanel();
	}

	/** Rounded card with an optional colored accent stripe on the left edge. */
	private static class CardPanel extends JPanel
	{
		private Color accent;

		CardPanel()
		{
			setOpaque(false);
			setBackground(CARD_BG);
			setBorder(new EmptyBorder(7, 10, 7, 8));
			setAlignmentX(JComponent.LEFT_ALIGNMENT);
		}

		void setAccent(Color accent)
		{
			this.accent = accent;
		}

		@Override
		public void setBackground(Color bg)
		{
			super.setBackground(bg);
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(getBackground());
			g2.fillRoundRect(0, 0, getWidth(), getHeight(), 8, 8);
			if (accent != null)
			{
				g2.setColor(accent);
				g2.fillRoundRect(0, 0, 4, getHeight(), 4, 4);
			}
			g2.dispose();
			super.paintComponent(g);
		}
