	private static JLabel mutedRow(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(OFFLINE_GRAY);
		label.setBorder(new EmptyBorder(2, 4, 2, 0));
		label.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		return label;
	}

	private static String badgeText(String type)
	{
		switch (type)
		{
			case "level": return "LVL";
			case "quest": return "QUEST";
			case "collection_log": return "CLOG";
			case "drop": return "DROP";
			case "death": return "DEATH";
			default: return "\u2022";
		}
	}

	private static Color badgeColor(String type)
	{
		switch (type)
		{
			case "level": return new Color(85, 170, 255);
			case "quest": return new Color(170, 130, 255);
			case "collection_log": return new Color(120, 200, 120);
			case "drop": return GOLD;
			case "death": return new Color(230, 90, 90);
			default: return ColorScheme.LIGHT_GRAY_COLOR;
		}
	}

	private static String timeAgo(long timestamp)
	{
		long seconds = Math.max(0, (System.currentTimeMillis() - timestamp) / 1000);
		if (seconds < 60)
		{
			return "now";
		}
		if (seconds < 3600)
		{
			return (seconds / 60) + "m";
		}
		if (seconds < 86400)
		{
			return (seconds / 3600) + "h";
		}
		return (seconds / 86400) + "d";
	}

	private static String escapeHtml(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Small round status indicator icon. */
	private static class StatusDot implements javax.swing.Icon
	{
		private final Color color;

		StatusDot(Color color)
		{
			this.color = color;
		}

		@Override
		public void paintIcon(java.awt.Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(color);
			g2.fillOval(x, y + 1, 8, 8);
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return 8;
		}

		@Override
		public int getIconHeight()
		{
			return 10;
		}
	}

	/** Simple generated icon so we don't need a binary resource in the repo. */
	static BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(90, 130, 90));
		g.fillRoundRect(1, 1, 14, 14, 5, 5);
		g.setColor(Color.WHITE);
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 9));
		g.drawString("G", 5, 12);
		g.dispose();
		return image;
	}
}

package com.gimtracker;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.WorldService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.WorldUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.http.api.worlds.World;
import net.runelite.http.api.worlds.WorldResult;
import com.google.inject.Provides;

@Slf4j
@PluginDescriptor(
	name = "GIM Discord Tracker",
	description = "Group Ironman tracker: in-game group panel + Discord dashboard and chat bridge. "
		+ "Sends presence, milestones and bank data to a server hosted by your own group.",
	tags = {"group", "ironman", "gim", "discord", "bank"}
)
public class GimTrackerPlugin extends Plugin
{
	private static final int FLUSH_INTERVAL_SECONDS = 15;
	private static final int PANEL_REFRESH_SECONDS = 30;
	private static final int CHAT_POLL_SECONDS = 5;

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private GimTrackerConfig config;

	@Inject
	private ApiClient api;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private WorldService worldService;

	@Inject
	private ClientThread clientThread;

	private GimTrackerPanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> flushTask;
	private ScheduledFuture<?> panelTask;
	private ScheduledFuture<?> chatTask;
	private volatile long lastChatId = -1;

	// State collected on the client thread, flushed on the executor
	private final Object lock = new Object();
	private final List<Map<String, Object>> pendingEvents = new ArrayList<>();
	private final Map<String, Integer> realLevels = new HashMap<>();
	private final Map<String, Integer> skillXp = new HashMap<>();
	private List<Map<String, Object>> pendingBank;
	private List<Map<String, Object>> pendingSharedBank;
	private Map<String, Object> pendingSkills;
	private int lastBankHash;
	private int lastSharedBankHash;
	private volatile String playerName;
	private volatile int world;
	private volatile boolean loggedIn;

	@Provides
	GimTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GimTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new GimTrackerPanel(api, itemManager, () ->
		{
			String name = playerName;
			return name != null ? name : "unknown";
		}, this::hopTo);

		BufferedImage icon = GimTrackerPanel.createIcon();
		navButton = NavigationButton.builder()
			.tooltip("GIM Tracker")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		flushTask = executor.scheduleWithFixedDelay(this::flush,
			FLUSH_INTERVAL_SECONDS, FLUSH_INTERVAL_SECONDS, TimeUnit.SECONDS);
		panelTask = executor.scheduleWithFixedDelay(panel::refresh,
			2, PANEL_REFRESH_SECONDS, TimeUnit.SECONDS);
		chatTask = executor.scheduleWithFixedDelay(this::pollChat,
			CHAT_POLL_SECONDS, CHAT_POLL_SECONDS, TimeUnit.SECONDS);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		if (flushTask != null)
		{
			flushTask.cancel(false);
		}
		if (panelTask != null)
		{
			panelTask.cancel(false);
		}
		if (chatTask != null)
		{
			chatTask.cancel(false);
		}
		lastChatId = -1;

		// Tell the server we're going offline
		loggedIn = false;
		flush();

		synchronized (lock)
		{
			pendingEvents.clear();
			pendingBank = null;
			pendingSharedBank = null;
			pendingSkills = null;
		}
		realLevels.clear();
		skillXp.clear();
		playerName = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			loggedIn = true;
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			loggedIn = state == GameState.HOPPING;
			realLevels.clear();
			skillXp.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player local = client.getLocalPlayer();
		if (local != null && local.getName() != null)
		{
			playerName = local.getName();
			world = client.getWorld();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		int real = client.getRealSkillLevel(skill);
		int xp = client.getSkillExperience(skill);
		Integer previous = realLevels.put(skill.getName(), real);
		Integer previousXp = skillXp.put(skill.getName(), xp);

		if (previous == null)
		{
			// First observation after login - record silently
			markSkillsDirty();
			return;
		}

		if (real > previous && config.shareEvents())
		{
			queueEvent("level", skill.getName() + " level " + real);
		}
		if (real != previous || previousXp == null || xp != previousXp)
		{
			markSkillsDirty();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();
		boolean shared = containerId == InventoryID.GROUP_STORAGE.getId();
		if (shared ? !config.shareGroupStorage()
			: (containerId != InventoryID.BANK.getId() || !config.shareBank()))
		{
			return;
		}

		ItemContainer container = event.getItemContainer();
		if (container == null)
		{
			return;
		}

		List<Map<String, Object>> items = new ArrayList<>();
		StringBuilder hashInput = new StringBuilder();
		for (Item item : container.getItems())
		{
			if (item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			ItemComposition comp = itemManager.getItemComposition(item.getId());
			if (comp.getPlaceholderTemplateId() != -1)
			{
				continue;
			}

			Map<String, Object> entry = new LinkedHashMap<>();
			entry.put("id", item.getId());
			entry.put("name", comp.getName());
			entry.put("qty", item.getQuantity());
			entry.put("price", itemManager.getItemPrice(item.getId()));
			items.add(entry);
			hashInput.append(item.getId()).append(':').append(item.getQuantity()).append(',');
		}

		int hash = Objects.hash(hashInput.toString());
		synchronized (lock)
		{
			if (shared)
			{
				if (hash == lastSharedBankHash)
				{
					return;
				}
				lastSharedBankHash = hash;
				pendingSharedBank = items;
			}
			else
			{
				if (hash == lastBankHash)
				{
					return;
				}
				lastBankHash = hash;
				pendingBank = items;
			}
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == client.getLocalPlayer() && config.shareEvents())
		{
			queueEvent("death", "died");
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		// Bridge the GIM chat channel to Discord
		if (event.getType() == ChatMessageType.CLAN_GIM_CHAT && config.bridgeChat())
		{
			String sender = event.getName().replaceAll("<[^>]*>", "").replace('\u00A0', ' ').trim();
			String text = event.getMessage().replaceAll("<[^>]*>", "").trim();
			if (!sender.isEmpty() && !text.isEmpty())
			{
				Map<String, Object> body = new HashMap<>();
				body.put("sender", sender);
				body.put("text", text);
				api.post("api/chat", body, null);
			}
			return;
		}

		if (event.getType() != ChatMessageType.GAMEMESSAGE || !config.shareEvents())
		{
			return;
		}

		String message = event.getMessage().replaceAll("<[^>]*>", "");
		if (message.startsWith("New item added to your collection log:"))
		{
			queueEvent("collection_log", message.substring(message.indexOf(':') + 1).trim());
		}
		else if (message.contains("you've completed a quest:"))
		{
			queueEvent("quest", message.substring(message.indexOf(':') + 1).trim());
		}
		else if (message.startsWith("Valuable drop:"))
		{
			queueEvent("drop", message.substring(message.indexOf(':') + 1).trim());
		}
	}

	private void queueEvent(String type, String text)
	{
		Map<String, Object> ev = new LinkedHashMap<>();
		ev.put("type", type);
		ev.put("text", text);
		ev.put("timestamp", System.currentTimeMillis());
		synchronized (lock)
		{
			pendingEvents.add(ev);
		}
	}

	private void markSkillsDirty()
	{
		Map<String, Object> snapshot = new HashMap<>();
		for (Map.Entry<String, Integer> entry : realLevels.entrySet())
		{
			Map<String, Object> stat = new LinkedHashMap<>();
			stat.put("level", entry.getValue());
			stat.put("xp", skillXp.getOrDefault(entry.getKey(), 0));
			snapshot.put(entry.getKey(), stat);
		}
		synchronized (lock)
		{
			pendingSkills = snapshot;
		}
	}

	/** Runs on the executor: pulls Discord messages and prints them in the chatbox. */
	private void pollChat()
	{
		if (!loggedIn || !config.bridgeChat() || config.groupToken().isEmpty())
		{
			return;
		}

		api.fetchChat(lastChatId, response ->
		{
			if (!response.has("latest"))
			{
				return;
			}
			lastChatId = response.get("latest").getAsLong();
			if (!response.has("messages"))
			{
				return;
			}
			for (JsonElement el : response.getAsJsonArray("messages"))
			{
				JsonObject msg = el.getAsJsonObject();
				String sender = msg.get("sender").getAsString().replaceAll("<[^>]*>", "");
				String text = msg.get("text").getAsString().replaceAll("<[^>]*>", "");
				clientThread.invokeLater(() ->
				{
					if (client.getGameState() == GameState.LOGGED_IN)
					{
						client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
							"<col=5865f2>[Discord] " + sender + ":</col> " + text, null);
					}
				});
			}
		});
	}

	/** Hop to another member's world (invoked from the side panel). */
	private void hopTo(int worldId)
	{
		WorldResult worlds = worldService.getWorlds();
		if (worlds == null)
		{
			return;
		}
		World world = worlds.findWorld(worldId);
		if (world == null)
		{
			return;
		}

		clientThread.invoke(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}
			net.runelite.api.World rsWorld = client.createWorld();
			rsWorld.setActivity(world.getActivity());
			rsWorld.setAddress(world.getAddress());
			rsWorld.setId(world.getId());
			rsWorld.setPlayerCount(world.getPlayers());
			rsWorld.setLocation(world.getLocation());
			rsWorld.setTypes(WorldUtil.toWorldTypes(world.getTypes()));
			client.hopToWorld(rsWorld);
		});
	}

	/** Runs on the executor: batches everything collected since the last flush into one request. */
	private void flush()
	{
		String name = playerName;
		if (name == null || config.groupToken().isEmpty())
		{
			return;
		}

		List<Map<String, Object>> events;
		List<Map<String, Object>> bank;
		List<Map<String, Object>> sharedBank;
		Map<String, Object> skills;
		synchronized (lock)
		{
			events = new ArrayList<>(pendingEvents);
			pendingEvents.clear();
			bank = pendingBank;
			pendingBank = null;
			sharedBank = pendingSharedBank;
			pendingSharedBank = null;
			skills = pendingSkills;
			pendingSkills = null;
		}

		Map<String, Object> payload = new LinkedHashMap<>();
		payload.put("player", name);
		payload.put("online", loggedIn && config.sharePresence());
		payload.put("world", world);
		if (!events.isEmpty())
		{
			payload.put("events", events);
		}
		if (bank != null)
		{
			payload.put("bank", bank);
		}
		if (sharedBank != null)
		{
			payload.put("sharedBank", sharedBank);
		}
		if (skills != null)
		{
			payload.put("skills", skills);
		}

		api.postUpdate(payload);
	}
}

